use crate::schema::{FieldDef, FieldType, TypeDef, UnionVariant};
use std::fmt::Write;

const HEADER: &str = "\
// ---------------------------------------------------------
// AUTO-GENERATED by generate-sdk-types — DO NOT EDIT
// Source: contracts/schemas/*.schema.json
// ---------------------------------------------------------";

pub fn emit(types: &[TypeDef]) -> String {
    let mut out = String::new();
    out.push_str(HEADER);
    out.push('\n');

    for typedef in types {
        out.push('\n');
        match typedef {
            TypeDef::StringEnum { name, variants } => {
                emit_string_enum(&mut out, name, variants);
            }
            TypeDef::TaggedUnion {
                name,
                discriminator,
                variants,
            } => {
                emit_tagged_union(&mut out, name, discriminator, variants);
            }
            TypeDef::Struct { name, fields } => {
                emit_struct(&mut out, name, fields);
            }
        }
    }

    out.push('\n');
    out
}

fn emit_string_enum(out: &mut String, name: &str, variants: &[String]) {
    if variants.len() <= 3 {
        let joined = variants
            .iter()
            .map(|v| format!("\"{v}\""))
            .collect::<Vec<_>>()
            .join(" | ");
        writeln!(out, "export type {name} = {joined};").expect("write");
    } else {
        writeln!(out, "export type {name} =").expect("write");
        for (i, v) in variants.iter().enumerate() {
            if i == variants.len() - 1 {
                writeln!(out, "  | \"{v}\";").expect("write");
            } else {
                writeln!(out, "  | \"{v}\"").expect("write");
            }
        }
    }
}

fn emit_tagged_union(out: &mut String, name: &str, discriminator: &str, variants: &[UnionVariant]) {
    writeln!(out, "export type {name} =").expect("write");
    for (i, variant) in variants.iter().enumerate() {
        let trailing = if i == variants.len() - 1 { ";" } else { "" };
        let mut parts = Vec::new();
        parts.push(format!("{discriminator}: \"{}\"", variant.tag_value));
        for field in &variant.fields {
            let ts_type = field_type_to_ts(&field.ty);
            if field.required {
                parts.push(format!("{}: {ts_type}", field.name));
            } else {
                parts.push(format!("{}?: {ts_type}", field.name));
            }
        }
        let body = parts.join("; ");
        writeln!(out, "  | {{ {body} }}{trailing}").expect("write");
    }
}

fn emit_struct(out: &mut String, name: &str, fields: &[FieldDef]) {
    writeln!(out, "export type {name} = {{").expect("write");
    for field in fields {
        let ts_type = field_type_to_ts(&field.ty);
        if field.required {
            writeln!(out, "  {}: {ts_type};", field.name).expect("write");
        } else if field.has_default {
            // For a non-null default, unwrap the outer Nullable — the SDK
            // fills the default and consumers never see null. For a null
            // default, keep the nullable wrapper because null IS the wire
            // value when the field is unset.
            let default_is_null = matches!(&field.default_value, Some(v) if v.is_null());
            let emit_ty = if default_is_null {
                ts_type.clone()
            } else {
                unwrap_nullable_for_ts(&field.ty)
            };
            writeln!(out, "  {}?: {emit_ty};", field.name).expect("write");
        } else {
            // Not required, no default — optional and nullable
            writeln!(out, "  {}?: {ts_type};", field.name).expect("write");
        }
    }
    writeln!(out, "}};").expect("write");
}

/// For fields with defaults, unwrap the outer Nullable layer if present,
/// since the SDK will provide the default.
fn unwrap_nullable_for_ts(ty: &FieldType) -> String {
    match ty {
        FieldType::Nullable(inner) => field_type_to_ts(inner),
        other => field_type_to_ts(other),
    }
}

fn field_type_to_ts(ty: &FieldType) -> String {
    match ty {
        FieldType::String => "string".to_string(),
        FieldType::Bool => "boolean".to_string(),
        FieldType::Int | FieldType::Float => "number".to_string(),
        FieldType::Ref(name) => name.clone(),
        FieldType::Array(inner) => {
            let inner_ts = field_type_to_ts(inner);
            if inner_ts.contains('|') {
                format!("({inner_ts})[]")
            } else {
                format!("{inner_ts}[]")
            }
        }
        FieldType::Map(inner) => {
            let inner_ts = field_type_to_ts(inner);
            format!("Record<string, {inner_ts}>")
        }
        FieldType::Nullable(inner) => {
            let inner_ts = field_type_to_ts(inner);
            format!("{inner_ts} | null")
        }
    }
}
